<?php require_once __DIR__.'/includes/bootstrap.php';$pageTitle='سبد خرید';include __DIR__.'/includes/header.php';?>
<main class="page-content container"><h1 class="page-title">سبد خرید شما</h1><div id="cart-view" class="table-wrap"></div><div class="center"><a class="btn btn-outline" href="products.php">ادامه خرید</a> <a class="btn btn-primary" href="checkout.php">ادامه و ثبت سفارش</a></div></main>
<script>
const cartBox=document.getElementById('cart-view');function drawCart(){let c=JSON.parse(localStorage.getItem('rosea_cart')||'[]');if(!c.length){cartBox.innerHTML='<p class="empty-state">سبد خرید شما خالی است.</p>';return}let total=c.reduce((s,x)=>s+x.price*x.qty,0);cartBox.innerHTML='<table class="data-table"><tr><th>محصول</th><th>قیمت</th><th>تعداد</th><th>جمع</th><th></th></tr>'+c.map((x,i)=>`<tr><td>${x.name}</td><td>${x.price.toLocaleString('fa-IR')} تومان</td><td><button onclick="changeQty(${i},-1)">−</button> ${x.qty} <button onclick="changeQty(${i},1)">+</button></td><td>${(x.price*x.qty).toLocaleString('fa-IR')} تومان</td><td><button onclick="removeItem(${i})">حذف</button></td></tr>`).join('')+'</table><h3>مبلغ کل: '+total.toLocaleString('fa-IR')+' تومان</h3>'}
function changeQty(i,n){let c=JSON.parse(localStorage.getItem('rosea_cart')||'[]');c[i].qty+=n;if(c[i].qty<1)c.splice(i,1);localStorage.setItem('rosea_cart',JSON.stringify(c));drawCart()}function removeItem(i){let c=JSON.parse(localStorage.getItem('rosea_cart')||'[]');c.splice(i,1);localStorage.setItem('rosea_cart',JSON.stringify(c));drawCart()}drawCart();
</script><?php include __DIR__.'/includes/footer.php';?>
